WITH order_items_by_product AS (SELECT product_id, MAX(unit_price) - MIN(unit_price) AS unit_price_range, MAX(unit_price) AS max_unit_price FROM order_items GROUP BY product_id) SELECT products.price, products.category, order_items_by_product.unit_price_range, order_items_by_product.max_unit_price FROM products JOIN order_items_by_product ON products.id = order_items_by_product.product_id WHERE order_items_by_product.unit_price_range >= 40 ORDER BY category, products.price DESC;
